package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void searching_by_part_of_title_returns_matching_books_with_id_title_and_status() throws Exception {
        String keyword = uniqueKeyword();
        String bookId = registerBookTitled("Spring in Action " + keyword);

        mockMvc.perform(get("/books").param("title", keyword))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].id").value(bookId))
                .andExpect(jsonPath("$[0].title").value("Spring in Action " + keyword))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void search_ignores_case() throws Exception {
        String keyword = uniqueKeyword();
        String bookId = registerBookTitled("Clean Code " + keyword);

        mockMvc.perform(get("/books").param("title", keyword.toLowerCase()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].id").value(bookId));
    }

    @Test
    void search_returns_every_book_containing_the_keyword() throws Exception {
        String keyword = uniqueKeyword();
        registerBookTitled("First " + keyword);
        registerBookTitled(keyword.toUpperCase() + " Second");

        mockMvc.perform(get("/books").param("title", keyword))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2));
    }

    @Test
    void search_without_matching_book_returns_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", uniqueKeyword()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void search_treats_wildcard_characters_literally() throws Exception {
        registerBookTitled("Plain " + uniqueKeyword());

        mockMvc.perform(get("/books").param("title", "%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void search_with_blank_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "   "))
                .andExpect(status().isBadRequest());
    }

    @Test
    void search_without_title_parameter_returns_400() throws Exception {
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private String uniqueKeyword() {
        return "kw" + UUID.randomUUID().toString().replace("-", "");
    }

    private String registerBookTitled(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }
}
